import os
from requests.utils import get_netrc_auth

# Create a dummy .netrc file with a valid entry
with open(".netrc_test", "w") as f:
    f.write("machine example.com login user password pass\n")

os.environ["NETRC"] = ".netrc_test"

try:
    auth = get_netrc_auth("http://example.com")
    print(f"Auth: {auth}")
    if auth == ('user', 'pass'):
        print("SUCCESS: Valid netrc entry worked")
    else:
        print(f"FAILURE: Valid netrc entry resulted in {auth}")
except Exception as e:
    print(f"Error: {e}")
finally:
    if os.path.exists(".netrc_test"):
        os.remove(".netrc_test")
    if "NETRC" in os.environ:
        del os.environ["NETRC"]

